function smallestPalindrome(s) {
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  let half = '';
  let middle = '';
  for (let letter = 0; letter < 26; letter++) {
    const ch = String.fromCharCode(97 + letter);
    half += ch.repeat(Math.floor(counts[letter] / 2));
    if (counts[letter] % 2 === 1) {
      middle = ch;
    }
  }
  const mirrored = [...half].reverse().join('');
  return half + middle + mirrored;
}

