function smallestPalindrome(s) {
  // The first half of the palindrome s already holds half of every letter; sorting it gives the smallest half.
  const n = s.length;
  const firstHalf = s.slice(0, Math.floor(n / 2)).split('').sort().join('');
  const center = n % 2 === 1 ? s[Math.floor(n / 2)] : '';
  return firstHalf + center + firstHalf.split('').reverse().join('');
}

