function generate(rand, size) {
  const large = size === 'large';
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pool = Array.from({ length: pick(1, large ? 26 : 4) }, () => String.fromCharCode(97 + pick(0, 25)));
  const letter = () => pool[pick(0, pool.length - 1)];
  const halfLength = large ? pick(4900, 4999) : pick(0, 4);
  const half = Array.from({ length: halfLength }, letter).join('');
  const middle = halfLength === 0 || rand() < 0.5 ? letter() : '';
  return [half + middle + [...half].reverse().join('')];
}
